use std::env;
use std::fs;
use std::path::PathBuf;

use base64::Engine as _;

#[path = "resource_ids.rs"]
mod resource_ids;
#[path = "build_support/resource_script.rs"]
mod resource_script;

const ICON_BASE64: &str = "";

const TOOLBAR1_BASE64: &str = "";
const TOOLBAR2_BASE64: &str = "";

fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("cargo:rerun-if-changed=build.rs");
    println!("cargo:rerun-if-env-changed=RC");
    if env::var_os("CARGO_CFG_WINDOWS").is_none() {
        return Ok(());
    }
    let output = PathBuf::from(env::var_os("OUT_DIR").ok_or("Cargo did not provide OUT_DIR")?);
    let icon = output.join("DarkReNamer.ico");
    let toolbar1 = output.join("toolbar1.bmp");
    let toolbar2 = output.join("toolbar2.bmp");
    let manifest = output.join("DarkReNamer.manifest");
    let resource = output.join("DarkReNamer.rc");
    let package_version = env::var("CARGO_PKG_VERSION")?;
    let version_numbers = [
        env::var("CARGO_PKG_VERSION_MAJOR")?.parse::<u16>()?,
        env::var("CARGO_PKG_VERSION_MINOR")?.parse::<u16>()?,
        env::var("CARGO_PKG_VERSION_PATCH")?.parse::<u16>()?,
        0,
    ];
    let bytes = base64::engine::general_purpose::STANDARD.decode(ICON_BASE64)?;
    fs::write(&icon, bytes)?;
    fs::write(
        &toolbar1,
        base64::engine::general_purpose::STANDARD.decode(TOOLBAR1_BASE64)?,
    )?;
    fs::write(
        &toolbar2,
        base64::engine::general_purpose::STANDARD.decode(TOOLBAR2_BASE64)?,
    )?;
    fs::write(&manifest, resource_script::application_manifest())?;
    fs::write(
        &resource,
        resource_script::render(
            &icon,
            &toolbar1,
            &toolbar2,
            &manifest,
            &package_version,
            version_numbers,
        ),
    )?;
    embed_resource::compile(resource, embed_resource::NONE).manifest_optional()?;
    Ok(())
}
